public class BZip2CompressorInputStream_read_TriageGen0Test {

    /**
     * Helper to create a valid BZip2 stream.
     * BZip2 files must start with the magic number: BZh
     */
    private InputStream createValidBZip2Stream(byte[] data) throws IOException {
        // In a real scenario, we'd use a BZip2CompressorOutputStream to create valid compressed data.
        // For unit testing the 'read' logic, we mock/simulate the underlying stream behavior.
        // However, since we are testing the BZip2CompressorInputStream class directly,
        // we'll use a real compressed byte array.
        // Magic: 42 5a 68 (BZh)
        byte[] bzip2Header = new byte[]{0x42, (byte) 0x5a, 0x68};
        ByteArrayInputStream bais = new ByteArrayInputStream(bzip2Header);
        // Note: This is a simplified approach. In a full integration test, 
        // we'd use actual compressed bytes. Here we focus on the 'read' method's boundary logic.
        return new BZip2CompressorInputStream(bais);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_offsNegative() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(is);
        bais.read(new byte[10], -1, 5);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_lenNegative() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(is);
        bais.read(new byte[10], 0, -1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_outOfBounds() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(is);
        bais.read(new byte[10], 5, 6); // 5 + 6 > 10
    }

    @Test(expected = IOException.class)
    public void testRead_streamClosed() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(is);
        bais.close();
        bais.read(new byte[10], 0, 5);
    }

    @Test
    public void testRead_lenZero() throws IOException {
        // Using a valid-ish stream to avoid immediate EOF/Error
        byte[] magic = {0x42, 0x5a, 0x68};
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(new ByteArrayInputStream(magic));
        byte[] dest = new byte[10];
        int result = bais.read(dest, 0, 0);
        Assert.assertEquals(0, result);
    }

    @Test
    public void testRead_eofReturnsMinusOne() throws IOException {
        // Creating a stream that will immediately return -1 from read0()
        // We use an empty stream which doesn't contain BZip2 magic, 
        // but we want to trigger the (b = read0()) >= 0 check failing.
        byte[] empty = new byte[0];
        BZip2CompressorInputStream bais = new BZip2CompressorInputStream(new ByteArrayInputStream(empty));

        byte[] dest = new byte[10];
        int result = bais.read(dest, 0, 5);

        // If read0() returns -1 immediately, destOffs == offs, returns -1
        Assert.assertEquals(-1, result);
    }

